// Real controls, progressive detail and restrained entrance cues.
const storyTabs=[...document.querySelectorAll('[data-tab]')];
function chooseTier(index){storyTabs.forEach((button,i)=>{button.setAttribute('aria-selected',String(i===index));button.tabIndex=i===index?0:-1;document.getElementById('tier-content-'+i).hidden=i!==index;});}
storyTabs.forEach((button,i)=>{button.addEventListener('click',()=>chooseTier(i));button.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(i+1)%3;if(event.key==='ArrowLeft')next=(i+2)%3;if(event.key==='Home')next=0;if(event.key==='End')next=2;if(next!==undefined){event.preventDefault();chooseTier(next);storyTabs[next].focus();}});});
document.querySelectorAll('[data-phase]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-phase]').forEach(b=>{const active=b===button;b.setAttribute('aria-pressed',String(active));document.getElementById('phase-'+b.dataset.phase).hidden=!active;});}));
const referenceItems=[...document.querySelectorAll('.references li')],search=document.getElementById('reference-search');let sourceFilter='all';
referenceItems.forEach(item=>{const text=item.textContent;item.dataset.category=/Cyberspace/.test(text)?'regulation':/Hunan/.test(text)?'case':'standards';});
function filterSources(){const query=search.value.trim().toLowerCase();let count=0;referenceItems.forEach(item=>{const visible=(sourceFilter==='all'||item.dataset.category===sourceFilter)&&item.textContent.toLowerCase().includes(query);item.hidden=!visible;if(visible)count++;});document.getElementById('source-count').textContent=count?`${count} of ${referenceItems.length} sources`:'No matching sources. Try a different keyword or category.';}
search.addEventListener('input',filterSources);document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{sourceFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filterSources();}));filterSources();
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-seen');entry.target.classList.remove('is-ready');observer.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('is-ready');observer.observe(el);});}
